create extension if not exists pgcrypto;
create type user_role as enum ('ADMIN', 'KITCHEN', 'WAITER');
create type order_status as enum ('REGISTERED', 'CONFIRMED', 'PREPARING', 'READY', 'DELIVERED', 'CLOSED', 'CANCELLED', 'REJECTED');

create table restaurants (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, timezone text not null default 'America/Lima', created_at timestamptz not null default now());
create table restaurant_users (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references restaurants(id) on delete cascade, auth_user_id uuid not null, role user_role not null, active boolean not null default true, unique (restaurant_id, auth_user_id));
create table dining_tables (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references restaurants(id) on delete cascade, code text not null, capacity smallint not null check (capacity > 0), qr_token_hash text not null, active boolean not null default true, unique (restaurant_id, code));
create table products (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references restaurants(id) on delete cascade, name text not null, description text not null default '', category text not null, price_cents integer not null check (price_cents >= 0), base_minutes smallint not null check (base_minutes > 0), available boolean not null default true, image_url text, created_at timestamptz not null default now());
create table table_sessions (id uuid primary key default gen_random_uuid(), table_id uuid not null references dining_tables(id), token_hash text not null unique, opened_at timestamptz not null default now(), expires_at timestamptz not null, closed_at timestamptz, check (expires_at > opened_at));
create table orders (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references restaurants(id), table_session_id uuid not null references table_sessions(id), status order_status not null default 'REGISTERED', notes text, subtotal_cents integer not null check (subtotal_cents >= 0), estimated_minutes smallint check (estimated_minutes > 0), idempotency_key text not null, created_at timestamptz not null default now(), confirmed_at timestamptz, ready_at timestamptz, closed_at timestamptz, unique (restaurant_id, idempotency_key));
create table order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id) on delete cascade, product_id uuid not null references products(id), product_name text not null, unit_price_cents integer not null check (unit_price_cents >= 0), quantity smallint not null check (quantity > 0), notes text);
create table order_events (id bigint generated always as identity primary key, order_id uuid not null references orders(id) on delete cascade, from_status order_status, to_status order_status not null, actor_user_id uuid, occurred_at timestamptz not null default now(), metadata jsonb not null default '{}'::jsonb);
create index orders_restaurant_status_idx on orders (restaurant_id, status, created_at);
create index order_events_order_time_idx on order_events (order_id, occurred_at);
